"""Self-contained component review. Every supplied string is inserted as text."""
import json


def render(payload):
    data = json.dumps(payload, ensure_ascii=True, sort_keys=True, allow_nan=False)
    data = data.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return PAGE.replace("__CONTEXT_DATA__", data)


PAGE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>Engineering component review</title><style>
:root{font:16px/1.5 system-ui,sans-serif;color:#193340;background:#f0f4f5}*{box-sizing:border-box}body{margin:0}
header{padding:1.2rem max(1rem,4vw);background:#193d48;color:white}h1{font-size:1.7rem;margin:0}h2{font-size:1.25rem}h3{font-size:1rem;margin:.3rem 0}
main{max-width:1400px;margin:auto;padding:1rem;display:grid;grid-template-columns:18rem minmax(0,1fr);gap:1rem}aside,section{min-width:0;background:white;padding:1rem;border-radius:6px}aside{align-self:start}section{margin-bottom:1rem}
label{display:block;margin:.6rem 0 .25rem}input,select,textarea,button{font:inherit;max-width:100%;border:1px solid #78929e;border-radius:4px;padding:.5rem}input,select,textarea{width:100%}textarea{min-height:6rem}button{cursor:pointer;background:#eaf3f6;color:#173d50;text-align:left;overflow-wrap:anywhere}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #40849c;outline-offset:2px}
#items{display:grid;gap:.4rem;max-height:60vh;overflow:auto;margin-top:.6rem}.active{border-left:5px solid #177484}.field{padding:.8rem 0;border-top:1px solid #d5e0e4}.field,.value,summary,pre,p,h2{overflow-wrap:anywhere}.value{border-left:3px solid #5c889b;padding:.5rem;margin:.5rem 0;background:#f4f8fa}.inactive{border-left-color:#ac6d2b;background:#fff5e9}.badge{font-size:.85rem;padding:.15rem .4rem;background:#e9f0f4;display:inline-block;border-radius:4px}.warn{padding:.6rem;border-left:4px solid #aa782b;background:#fff5e7;color:#4b3a21}small{color:#4a6371}pre{white-space:pre-wrap;font-size:.8rem}#message{min-height:1.5rem}footer{padding:1rem;max-width:1400px;margin:auto}
@media(max-width:760px){main{display:block}aside{margin-bottom:1rem}#items{max-height:12rem}h1{font-size:1.4rem}}
</style></head><body><header><h1>Engineering component review</h1><p>Inspect the shared facts, their sources and missing context. Keep a proposed edit for the next revision.</p></header>
<main><aside><label for="search">Find a tag or scoped item</label><input id="search" type="search" placeholder="e.g. P-101"><p id="count" aria-live="polite"></p><div id="items"></div></aside>
<article><section><h2 id="heading">Choose a scoped item</h2><p id="identity"></p><p class="warn">Drafts need engineering review. A recorded value or control link does not establish installed truth, safe action or an operating strategy.</p><label for="target">Component draft</label><select id="target" disabled></select><div id="fields"></div></section>
<section id="edit-section" hidden><h2>Propose a text edit</h2><p>The source facts stay visible. This saves an editorial proposal with its source dependencies; it does not approve or replace them.</p><label for="field">Field</label><select id="field"></select><label for="value">Proposed text or review note</label><textarea id="value" maxlength="32768"></textarea><label for="rationale">Reason and evidence still needed</label><textarea id="rationale" maxlength="32768" required></textarea><button id="download" type="button">Download proposed edit</button><p id="message" role="status"></p><p>Keep the downloaded file. Ask your agent to apply it to the packet with <code>context_workflow.py apply-review</code>, then reopen the generated review. No JSON editing is required.</p><div id="notes"></div></section>
<section><h2>Continuing use</h2><p>This portable foundation is useful before a product account: keep the original records, inspect disagreements and reuse the same context for drafts. A managed service adds ongoing access, authenticated history and maintained source ownership. Receiving into a governed service still needs its separate qualification.</p><p class="warn">This view is selected for review, not redacted for sharing. The underlying packet contains complete private originals and retained history. Check permitted scope and source access before handing anything to another person or service.</p><details><summary>Retained omissions and boundaries</summary><pre id="limits"></pre></details></section></article></main>
<footer>Company systems retain source authority. Proposed edits and generated drafts are not independent corroboration.</footer>
<script id="context-data" type="application/json">__CONTEXT_DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('context-data').textContent);
const byId=id=>document.getElementById(id);let selected=null;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function stateLabel(value){return ({sourced_unreviewed:'Source accounts available',disputed:'Sources disagree',unknown:'Not supplied',inactive_evidence:'Only inactive evidence',proposed_editorial:'Proposed edit',needs_rebase:'Needs review against changed sources',subject_unavailable:'Item absent from current inputs'})[value]||value.replaceAll('_',' ');}
function option(value,label){const n=el('option',label);n.value=value;return n;}
function drawItems(){const term=byId('search').value.toLowerCase();const items=data.items.filter(i=>(i.id+' '+i.tag).toLowerCase().includes(term));byId('items').replaceChildren();byId('count').textContent=items.length+' matching scoped items; choose the full identity.';for(const item of items){const b=el('button',item.id);b.type='button';b.dataset.subject=item.id;if(selected&&selected.id===item.id)b.className='active';b.onclick=()=>choose(item);byId('items').append(b);}}
function drawFields(){const target=selected.targets[byId('target').value];byId('fields').replaceChildren();if(!target){byId('fields').append(el('p','This component has no sourced item in the selected context.'));return;}for(const [name,field] of target.field_order.map(name=>[name,target.fields[name]])){const box=el('div',undefined,'field');box.dataset.field=name;box.append(el('h3',name.replaceAll('_',' ')),el('span',stateLabel(field.state),'badge'));if(!field.evidence.length)box.append(el('p','Not supplied. Retain this gap; do not infer a value.'));for(const row of field.evidence){const v=el('div',undefined,'value'+(row.active?'':' inactive'));v.append(el('p',row.value_display+(row.unit_text==='null'?'':' '+row.unit_display)),el('small',(row.active?'Retained source account':'INACTIVE evidence')+' · '+row.source_id+' · '+row.source_label+' · revision '+row.revision_label+' · '+row.locator));if(row.direction!==null)v.append(el('p','Recorded direction: '+row.direction));const detail=el('details');detail.append(el('summary','Source version, review and lineage'),el('p','Declared owner: '+row.owner_label),el('p','Applicability: '+row.applicability_label),el('pre',row.source_text+'\nReview: '+row.review_text+'\nLineage: '+row.lineage_text));v.append(detail);box.append(v);}byId('fields').append(box);}}
function choose(item){selected=item;byId('heading').textContent=item.tag;byId('identity').textContent=item.id+' · '+item.role.replaceAll('_',' ');byId('target').replaceChildren(...Object.entries(item.targets).map(([k,v])=>option(k,v.label)));byId('target').disabled=false;byId('field').replaceChildren(...Object.keys(item.edit_fields).map(k=>option(k,k.replaceAll('_',' '))));byId('field').value='draft_review_note';byId('value').value='';byId('rationale').value='';byId('message').textContent='';byId('edit-section').hidden=false;byId('notes').replaceChildren(el('h3','Retained editorial proposals'));for(const n of item.notes)byId('notes').append(el('p',n.field+': '+n.value_text+' · '+stateLabel(n.state)+' · '+n.rationale));drawFields();drawItems();}
byId('download').onclick=()=>{if(!selected)return;const rationale=byId('rationale').value.trim();if(!rationale){byId('message').textContent='Add a reason and the evidence still needed before downloading.';byId('rationale').focus();return;}const field=byId('field').value;const basis=selected.edit_fields[field];const request={schema:data.schema,basis_sha256:data.basis_sha256,receipt_sha256:data.receipt_sha256,subject:selected.id,field,value:byId('value').value,rationale,expected_content_fingerprint:basis.content_fingerprint,expected_evidence_fingerprint:basis.evidence_fingerprint,roots:basis.roots};const url=URL.createObjectURL(new Blob([JSON.stringify(request,null,2)+'\n'],{type:'application/json'}));const a=el('a');a.href=url;a.download='context-review-edit.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);byId('message').textContent='Proposed edit downloaded. Apply it to this exact retained packet, then regenerate the review.';};
byId('search').oninput=drawItems;byId('target').onchange=drawFields;byId('limits').textContent='Omissions: '+data.omissions_text+'\nBoundaries: '+data.boundaries_text;drawItems();
</script></body></html>'''
